WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT device_code, CASE WHEN pressure >= 1029 THEN 'LARGE' ELSE 'SMALL' END AS pressure_tier, MIN(reading_ts) AS started_at, AVG(pressure) FILTER (WHERE device_code = 'DV-01') AS dv_01_avg_pressure, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count FROM islands GROUP BY 1, 2 ORDER BY dv_01_count DESC;
